  if (matchScore != null) { const score = document.createElement('span'); score.className = 'score'; score.textContent = `${Math.round(matchScore * 100)}% match`; top.append(score); }
  wrapper.append(top);
  const facts = document.createElement('div'); facts.className = 'pub-facts'; const explanation = (options.reasons?.[0] || '').toLowerCase(); const personalReason = options.personalReason || pub.recommendationPersonalReason || ''; if (personalReason) { const match = personalReason.match(/^(Similar vibe to|Less similar to) (.+?)(?:, which you rated.*)?$/); const fact = document.createElement('span'); fact.className = 'fact personal-fact'; fact.textContent = match ? `${match[1] === 'Similar vibe to' ? 'Similar to' : 'Less like'} ${match[2]}` : personalReason; facts.append(fact); } const uniqueTags = featureTags(pub).filter((tag) => !explanation.includes(tag.toLowerCase())).slice(0, 4); uniqueTags.forEach((tag) => { const fact = document.createElement('span'); fact.className = 'fact'; fact.textContent = tag; facts.append(fact); }); if (!facts.children.length) facts.hidden = true; wrapper.append(facts);
  const links = document.createElement('div'); links.className = 'card-links'; const website = safeUrl(pub.website); if (website) { const websiteLink = document.createElement('a'); websiteLink.href = website; websiteLink.target = '_blank'; websiteLink.rel = 'noopener noreferrer'; websiteLink.textContent = 'Website ↗'; links.append(websiteLink); } if (pub.phone) { const phoneLink = document.createElement('a'); phoneLink.href = `tel:${String(pub.phone).replace(/[^+\d]/g, '')}`; phoneLink.textContent = `☎ ${pub.phone}`; links.append(phoneLink); } if (links.children.length) wrapper.append(links);
  if (options.diary || options.saved) { const review = document.createElement('div'); review.className = 'diary-memory'; if (state.reviews[pub.id]) { review.textContent = `“${state.reviews[pub.id]}”`; } else { review.textContent = 'No review yet'; } wrapper.append(review); const photos = state.photos[pub.id] || []; if (photos.length) { const gallery = document.createElement('div'); gallery.className = 'photo-grid'; photos.forEach((photo) => { const image = document.createElement('img'); image.src = photo; image.alt = `Memory from ${pub.name}`; gallery.append(image); }); wrapper.append(gallery); } }
  const actions = document.createElement('div'); actions.className = 'card-actions';
  const visited = state.visited.has(pub.id); if (visited) { const visit = document.createElement('button'); visit.className = 'visit-button visited'; visit.textContent = 'Visited'; visit.setAttribute('aria-pressed', 'true'); visit.onclick = () => { state.visited.delete(pub.id); delete state.visitCounts[pub.id]; persist(); void syncAccountRating(pub.id, { beenHere: false, rating: Number(state.ratings[pub.id]) || null }); renderAll(); toast('Removed from your diary'); }; actions.append(visit); const photo = document.createElement('button'); photo.className = 'memory-action'; photo.textContent = 'Add photo'; photo.onclick = () => addPhoto(pub); actions.append(photo); const review = document.createElement('button'); review.className = 'memory-action'; review.textContent = state.reviews[pub.id] ? 'Edit review' : 'Add review'; review.onclick = () => openReviewForm(pub); actions.append(review); } else { const visit = document.createElement('button'); visit.className = 'visit-button'; visit.textContent = 'Mark visited'; visit.setAttribute('aria-pressed', 'false'); visit.onclick = () => { if (!state.pubs.some((candidate) => candidate.id === pub.id)) state.pubs.push(pub); state.visited.add(pub.id); state.visitCounts[pub.id] = 1; persist(); void syncAccountRating(pub.id, { beenHere: true, rating: Number(state.ratings[pub.id]) || null }); renderAll(); toast('Added to your diary'); }; actions.append(visit); }
  const save = document.createElement('button'); save.className = `save-button${state.saved.has(pub.id) ? ' saved' : ''}`; save.textContent = state.saved.has(pub.id) ? '♥ Saved' : '♡ Save'; save.onclick = () => { if (!state.pubs.some((candidate) => candidate.id === pub.id)) state.pubs.push(pub); state.saved.has(pub.id) ? state.saved.delete(pub.id) : state.saved.add(pub.id); persist(); renderAll(); toast(state.saved.has(pub.id) ? 'Saved for later' : 'Removed from saved'); }; actions.append(save);
