function reportRatingFeedback(venueId, rating) { const eventType = rating > 4 ? 'like' : rating < 2 ? 'dislike' : null; if (!eventType) return; const recommendationRank = state.aiResults?.findIndex((item) => item.venueId === venueId); void fetch(`${API_URL}/feedback`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ venueId, eventType, query: state.query || null, recommendationRank: recommendationRank != null && recommendationRank >= 0 ? recommendationRank + 1 : null, requestId: state.aiContext?.requestId || null, rankingVersion: state.aiContext?.rankingVersion || null, datasetVersion: state.aiContext?.datasetVersion || null }) }).catch(() => {}); }
