async function accountRequest(path, options = {}) { const response = await fetch(`${API_URL}${path}`, { ...options, credentials: 'include', headers: { 'Content-Type': 'application/json', ...(options.headers || {}) } }); if (!response.ok) { const error = await response.json().catch(() => ({})); throw new Error(error.detail || 'Account request failed'); } return response.status === 204 ? null : response.json(); }
function updateAccountButton() { const button = $('#header-profile'); button.textContent = state.account ? 'AD' : 'PD'; button.title = state.account ? `Signed in as ${state.account.email}` : 'Sign in to save your rankings'; }
function applyAccountRatings(ratings) { ratings.forEach((rating) => { const value = Number(rating.rating); if (Number.isFinite(value)) state.ratings[rating.venueId] = value; else delete state.ratings[rating.venueId]; if (rating.beenHere) { state.visited.add(rating.venueId); state.visitCounts[rating.venueId] = Math.max(1, Number(state.visitCounts[rating.venueId] || 0)); } else { state.visited.delete(rating.venueId); delete state.visitCounts[rating.venueId]; } if (rating.privateNote) state.reviews[rating.venueId] = rating.privateNote; }); }
async function syncAccountRating(venueId, values) { if (!state.account) return; try { await accountRequest(`/account/ratings/${encodeURIComponent(venueId)}`, { method: 'PUT', body: JSON.stringify(values) }); } catch { toast('Your local change was saved, but the account could not be updated'); } }
async function importLocalRatings(remoteRatings) { const remoteIds = new Set(remoteRatings.map((rating) => rating.venueId)); const localIds = new Set([...Object.keys(state.ratings), ...state.visited]); for (const venueId of localIds) { if (remoteIds.has(venueId)) continue; await syncAccountRating(venueId, { beenHere: state.visited.has(venueId), rating: Number(state.ratings[venueId]) || null, privateNote: state.reviews[venueId] || null }); } }
async function loadAccount() { try { const account = await accountRequest('/account/me'); const initialRatings = await accountRequest('/account/ratings'); state.account = account; await importLocalRatings(initialRatings); const ratings = await accountRequest('/account/ratings'); applyAccountRatings(ratings); persist(); updateAccountButton(); renderAll(); } catch { state.account = null; updateAccountButton(); } }
function openLoginDialog() { const dialog = $('#login-dialog'); const signedIn = Boolean(state.account); $('#login-title').textContent = signedIn ? `Signed in as ${state.account.email}` : 'Sign in to save your rankings'; $('#login-copy').textContent = signedIn ? 'Your ratings and visits are saved to this account.' : 'Your ratings, visits and recommendations will follow you between sessions.'; $('#login-email').disabled = signedIn; $('#login-password').disabled = signedIn; $('#login-submit').hidden = signedIn; $('#logout-button').hidden = !signedIn; $('#login-message').textContent = ''; dialog.showModal(); }
$('#header-profile').addEventListener('click', openLoginDialog); $('#close-login').addEventListener('click', () => $('#login-dialog').close());
$('#login-form').addEventListener('submit', async (event) => { event.preventDefault(); if (state.account) return; const submit = $('#login-submit'); const message = $('#login-message'); submit.disabled = true; message.textContent = 'Signing in…'; try { state.account = await accountRequest('/account/login', { method: 'POST', body: JSON.stringify({ email: $('#login-email').value, password: $('#login-password').value }) }); await loadAccount(); $('#login-dialog').close(); toast('Your rankings are now saved to your account'); } catch (error) { state.account = null; message.textContent = error.message || 'Could not sign in'; } finally { submit.disabled = false; } });
$('#logout-button').addEventListener('click', async () => { try { await accountRequest('/account/logout', { method: 'POST' }); } finally { state.account = null; state.ratings = {}; state.reviews = {}; state.photos = {}; state.visitCounts = {}; state.visited.clear(); persist(); updateAccountButton(); renderAll(); $('#login-dialog').close(); toast('Signed out'); } });
$('#review-form').addEventListener('submit', () => { const pubId = $('#review-dialog').dataset.pubId; const rating = Number($('#rating-picker')?.dataset.value); if (pubId && state.account) window.setTimeout(() => { void syncAccountRating(pubId, { beenHere: state.visited.has(pubId), rating: Number(state.ratings[pubId]) || rating || null, privateNote: state.reviews[pubId] || null }); }, 0); });
void loadAccount();

// Keep Explore empty until the user asks for something. The full venue dataset still loads in the background for search and Diary.
function renderResults() { const container = $('#results'); container.replaceChildren(); const aiMode = state.aiResults !== null; const hasQuery = Boolean(state.query.trim()); $('#browse-controls').hidden = aiMode || !hasQuery; $('#results-title').textContent = aiMode ? `Your picks for “${state.query}”` : hasQuery ? `Browse results for “${state.query}”` : 'Search for pubs'; if (!hasQuery) { $('#status').textContent = state.pubs.length ? 'Search by area, feature, or preference to see pubs.' : 'Loading pubs…'; return; } if (aiMode) { if (!state.aiResults.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = state.aiContext?.noResultReasons?.[0] || 'No verified matches for that request yet. Try a broader search.'; container.append(empty); return; } const shown = state.recommendationsExpanded ? Math.min(state.aiVisibleCount, state.aiResults.length) : Math.min(6, state.aiResults.length); state.aiResults.slice(0, shown).forEach((item) => container.append(card(aiPub(item), { recommended: true, reasons: item.reasons }))); $('#status').textContent = `Showing ${shown} of ${state.aiResults.length} pubs`; if (state.aiResults.length > 6) { const more = document.createElement('button'); more.className = 'view-more-button'; container.append(more); } } else { if (!state.filtered.length) { const empty = document.createElement('div'); empty.className = 'empty-state'; empty.textContent = 'No pubs are available to browse yet.'; container.append(empty); return; } const expanded = container.classList.contains('browse-expanded'); state.filtered.slice(0, expanded ? 60 : 12).forEach((pub) => container.append(card(pub))); } decorateCards(); if (state.view === 'map') renderMap(); }
